import{_ as r,o as n,c as i,ae as t}from"./chunks/framework.BvHJbMD4.js";const g=JSON.parse('{"title":"Die Gebrüder Alsberg und die Arisierung","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/alsberg-brueder.md","filePath":"recherche/alsberg-brueder.md"}'),a={name:"recherche/alsberg-brueder.md"};function s(d,e,u,l,o,h){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="die-gebruder-alsberg-und-die-arisierung" tabindex="-1">Die Gebrüder Alsberg und die Arisierung <a class="header-anchor" href="#die-gebruder-alsberg-und-die-arisierung" aria-label="Permalink to &quot;Die Gebrüder Alsberg und die Arisierung&quot;">​</a></h1><p>In der historischen Realität (und als tragischer Anker unserer Mockumentary) stellt das Schicksal der Familie Alsberg den dunkelsten Punkt in der Entstehungsgeschichte des Horten-Vermögens dar.</p><h2 id="wer-waren-die-gebruder-alsberg" tabindex="-1">Wer waren die Gebrüder Alsberg? <a class="header-anchor" href="#wer-waren-die-gebruder-alsberg" aria-label="Permalink to &quot;Wer waren die Gebrüder Alsberg?&quot;">​</a></h2><p>Siegfried und Alfred Alsberg betrieben ein erfolgreiches Warenhaus-Imperium mit Sitzen in Bochum, Gelsenkirchen und weiteren Städten. Ihre Häuser galten als modern, kundenorientiert und waren fester Bestandteil des städtischen Lebens.</p><h2 id="die-ubernahme-durch-helmut-horten-1933-1938" tabindex="-1">Die Übernahme durch Helmut Horten (1933-1938) <a class="header-anchor" href="#die-ubernahme-durch-helmut-horten-1933-1938" aria-label="Permalink to &quot;Die Übernahme durch Helmut Horten (1933-1938)&quot;">​</a></h2><p>Im Jahr 1933, kurz nach der Machtübernahme der Nationalsozialisten, übernahm der erst 24-jährige Helmut Horten das Warenhaus Alsberg in Duisburg. Dies war der Grundstein für seinen späteren Aufstieg zum &quot;Kaufhauskönig&quot;.</p><h3 id="die-mechanismen-der-arisierung" tabindex="-1">Die Mechanismen der &quot;Arisierung&quot;: <a class="header-anchor" href="#die-mechanismen-der-arisierung" aria-label="Permalink to &quot;Die Mechanismen der &quot;Arisierung&quot;:&quot;">​</a></h3><ul><li><strong>Wirtschaftlicher Druck:</strong> Durch Boykottaufrufe und Repressalien gegen jüdische Geschäfte wurden die Eigentümer in die Enge getrieben.</li><li><strong>Kreditentzug:</strong> Banken (wie im Film durch <em>Bankier Schreck</em> repräsentiert) kündigten Kredite oder verweigerten neue Mittel.</li><li><strong>Unterpreisige Verkäufe:</strong> Die Verkäufe fanden oft unter extremem Zeitdruck und zu Bruchteilen des tatsächlichen Wertes statt.</li></ul><h2 id="das-schicksal-der-personen" tabindex="-1">Das Schicksal der Personen <a class="header-anchor" href="#das-schicksal-der-personen" aria-label="Permalink to &quot;Das Schicksal der Personen&quot;">​</a></h2><p>Während Helmut Horten nach dem Krieg sein Imperium halten und ausbauen konnte, war das Schicksal der ursprünglichen Eigentümer von Verfolgung und Exil geprägt.</p><ul><li><strong>Siegfried Alsberg:</strong> Musste sein Lebenswerk unter Zwang abgeben. Er starb 1941 in der Emigration.</li><li><strong>Alfred Alsberg:</strong> Wurde deportiert und im Holocaust ermordet.</li></ul><h2 id="in-der-mockumentary" tabindex="-1">In der Mockumentary <a class="header-anchor" href="#in-der-mockumentary" aria-label="Permalink to &quot;In der Mockumentary&quot;">​</a></h2><p>In unserem Film nutzen wir dieses Schicksal als moralisches Gegengewicht zur glitzernden Welt der Heidi Horten. Während die Witwe von &quot;Pointillismus&quot; und &quot;Mäzenatentum&quot; spricht, zeigen wir in Teil 3 die nüchterne, bürokratische Kälte, mit der Helmut Horten die &quot;Marktbereinigung&quot; vorantrieb.</p><p>August Diehl spielt Horten hier als einen Mann, der sich hinter Paragrafen und &quot;marktüblichen Bedingungen&quot; versteckt, während er das Leid der Betroffenen ignoriert.</p>',14)])])}const m=r(a,[["render",s]]);export{g as __pageData,m as default};
